sys_script_include.script:
function HtmlRenderBusinessProcess(vBusinessProcess)
{
	var IsValidRecord = x_snc_devtools.IsValidRecord;
	var HtmlRenderError = x_snc_devtools.HtmlRenderError;
	var HtmlRenderWarning = x_snc_devtools.HtmlRenderWarning;
	var HtmlRenderTableOfContents = x_snc_devtools.HtmlRenderTableOfContents;
	var ParseJson = x_snc_devtools.ParseJson;
	var GetStringValue = x_snc_devtools.GetStringValue;
	var GetValue = x_snc_devtools.GetValue;
	var GetArrayValue = x_snc_devtools.GetArrayValue;
	var HtmlEncode = x_snc_devtools.HtmlEncode;
	var ArrayGetElementById = x_snc_devtools.ArrayGetElementById;
	var IsObject = x_snc_devtools.IsObject;


	var grBusinessProcess = GetBusinessProcessRecord(vBusinessProcess);
	if (IsValidRecord(grBusinessProcess) == false)
	{
		return HtmlRenderError('Could not load the given Business Process record!');
	}

	var strHtml = '';

	strHtml += '<h1>' + grBusinessProcess.name + '</h1>';
	strHtml += '<p>' + grBusinessProcess.number + '</p>';

	var strDescription = GetStringValue(grBusinessProcess.summary);
	if (strDescription == '')
	{
		strDescription = GetStringValue(grBusinessProcess.description);
	}

	if (strDescription == '')
	{
		strHtml += HtmlRenderWarning('The business process does not (yet) have a description!');
	}
	else
	{
		strHtml += '<p>' + strDescription + '</p>';
	}

	var details = ParseJson(grBusinessProcess.json);

	if (x_snc_devtools.IsObject(details) == false)
	//if (BusinessProcessValidate(details,false) == false)
	{
		strHtml += HtmlRenderWarning('No details have been defined for the business process!');
		return strHtml;
	}

	strHtml += HtmlRenderTableOfContents();


	var strOutput = GetStringValue(GetValue(details,'output'));
	if (strOutput != '')
	{
		strHtml += '<h2>Output</h2>';
		strHtml += '<p>' + HtmlEncode(strOutput) + '</p>';
	}

	var strInput = GetStringValue(GetValue(details,'input'));
	if (strInput != '')
	{
		strHtml += '<h2>Input</h2>';
		strHtml += '<p>' + HtmlEncode(strInput) + '</p>';
	}

	strHtml += '<h2>Roles</h2>';

	var aRoles = GetArrayValue(GetValue(details,'_roles'));

	if (aRoles.length == 0)
	{
		strHtml += HtmlRenderWarning('No roles have been defined for the business process!');
	}
	else
	{
		for (var nRole = 0; nRole < aRoles.length; nRole++)
		{
			var role = aRoles[nRole];
			var strName = GetValue(role,'name');
			var strDescription = GetValue(role,'description');

			strHtml += '<h3>' + strName + '</h3>';
			strHtml += '<p>' + strDescription + '</p>'; 
		}
	}

	strHtml += '<h2>States</h2>';

	var aStates = GetArrayValue(GetValue(details,'_states'));
	var aTransitions = GetArrayValue(GetValue(details,'_transitions'));

	if (aStates.length == 0)
	{
		strHtml += HtmlRenderWarning('No states (steps) have been defined for the business process!');
	}
	else
	{
		for (var nState = 0; nState < aStates.length; nState++)
		{
			var state = aStates[nState];
			var strName = GetValue(state,'name');
			var strDescription = GetValue(state,'description');

			strHtml += '<h3>' + strName + '</h3>';
			strHtml += '<p>' + strDescription + '</p>'; 

			var aTransitionIds = GetArrayValue(GetValue(state,'_transitions'));

			if (aTransitionIds.length > 0)
			{
				var strHtmlTransitions = '';
				for (var nTransition = 0; nTransition < aTransitionIds.length; nTransition++)
				{
					var strTransitionId = aTransitionIds[nTransition];

					var transition = ArrayGetElementById(aTransitions,strTransitionId);

					if (IsObject(transition) == true)
					{
						var strTargetStateId = GetStringValue(GetValue(transition,'target_state'));
						if (strTargetStateId != '')
						{
							var target_state = ArrayGetElementById(GetValue(details,'_states'),strTargetStateId);
							if (IsObject(target_state) == true)
							{
								if (strHtmlTransitions != '')
								{
									strHtmlTransitions += ', ';
								}
								strHtmlTransitions += '<b>' + HtmlEncode(target_state.name) + '</b>';
							}
						}
					}

				}
				strHtml += '<p>Transition to: ' + strHtmlTransitions + '</p>';
			}

		}
	}

/*
	strHtml += '<h2>Transitions</h2>';
*/

/*
	strHtml += '<h2>Integrations</h2>';
*/

	return strHtml;
}
